.slidey-gp-edge { fill: none; stroke-linecap: round; stroke-linejoin: round; }.slidey-gp-gnode text { text-anchor: middle; dominant-baseline: middle; }.slidey-gp-gnode rect { filter: drop-shadow(rgba(0, 0, 0, 0.38) 0px 12px 20px); }.slidey-gp-gnode.pulse rect { animation: 1.5s ease-in-out 0s infinite normal none running slidey-gp-pulse; }.slidey-gp-gnode.fail rect { animation: 1.4s ease-in-out 0s infinite normal none running slidey-gp-failpulse; }@keyframes slidey-gp-pulse { 
  0%, 100% { filter: drop-shadow(rgba(56, 189, 248, 0.25) 0px 0px 8px); }
  50% { filter: drop-shadow(rgba(56, 189, 248, 0.68) 0px 0px 28px); }
}@keyframes slidey-gp-failpulse { 
  0%, 100% { filter: drop-shadow(rgba(251, 113, 133, 0.3) 0px 0px 6px); }
  50% { filter: drop-shadow(rgba(251, 113, 133, 0.8) 0px 0px 24px); }
}
